# Hypothesis: full group-balanced refit gives a better worst-group/mean frontier than the rank-1 edit; quantify with threshold sweeps on held-out CV scores.
def frontier(S, mean_floors=(95.0,95.5,96.0), ngrid=400):
    allv = np.sort(S.ravel()); thr = np.quantile(allv, np.linspace(0.02,0.98,ngrid))
    res = []
    for t in thr:
        a = accs_from_scores(S, t); res.append((t, a.min(), np.dot(a,gw), *a))
    res = np.array(res)
    out = {}
    for mf in mean_floors:
        ok = res[res[:,2]>=mf]
        if len(ok)==0: out[mf]=None; continue
        best = ok[np.argmax(ok[:,1]+1e-6*ok[:,2])]
        out[mf] = best
    return out, res
def show_frontier(name, S):
    out,_ = frontier(S)
    parts = []
    for mf,bst in out.items():
        if bst is None: parts.append(f'[mean>={mf}: none]')
        else: parts.append(f'[mean>={mf}: worst {bst[1]:.1f} (mean {bst[2]:.2f}; LL {bst[3]:.1f} LW {bst[4]:.1f} WL {bst[5]:.1f} WW {bst[6]:.1f})]')
    print(f'{name:28s}', ' '.join(parts))
